def run_stack_via_list(operations):
    # Simulate a linked-list stack (head insert/remove); return pop results (-1 when empty).
    head = None  # each node is [value, next]
    results = []
    for op in operations:
        if op[0] == "push":
            head = [op[1], head]
        else:
            if head is None:
                results.append(-1)
            else:
                results.append(head[0])
                head = head[1]
    return results

