#include <bits/stdc++.h>
using namespace std;

class MyStack {
private:
    struct StackNode { int data; StackNode* next; };
    StackNode* top = nullptr;
public:
    void push(int x) { top = new StackNode{x, top}; }
    int pop() {
        if (!top) return -1;
        int val = top->data;
        StackNode* dead = top;
        top = top->next;
        delete dead;
        return val;
    }
};

