class MyStack {
    private static class StackNode {
        int data; StackNode next;
        StackNode(int d, StackNode n) { data = d; next = n; }
    }
    private StackNode top = null;

    public void push(int x) { top = new StackNode(x, top); }

    public int pop() {
        if (top == null) return -1;
        int val = top.data;
        top = top.next;
        return val;
    }
}
